#!/usr/bin/env python3
"""Split an ordered suite into N contiguous, time-balanced shards and generate one JUnit suite per shard.

Etendo tests can depend on execution order (e.g. costing), and Gradle does not run classes in the
order given by --tests. So each shard is a contiguous slice of the original suite order, emitted as
a generated @Suite/@SelectClasses class, which preserves that order. Each shard starts from a fresh
DB snapshot in CI.

Usage: plan-shards.py SUITE_FILE TIMINGS_JSON N OUT_DIR [--java-dir src-test/src]
  SUITE_FILE    ordered units (from build-suites.py); <suite>.units.json maps units to leaf classes
  TIMINGS_JSON  per-class seconds (report.py timings.json); unknown classes get the median
Writes OUT_DIR/shard-<i>.txt (the generated suite class to run) and
JAVA_DIR/org/openbravo/qa/shards/QaShard<i>.java. Prints the GitHub Actions matrix JSON.
"""
import argparse, glob, json, os, re, statistics, sys

ap = argparse.ArgumentParser()
ap.add_argument("suite"); ap.add_argument("timings"); ap.add_argument("n", type=int); ap.add_argument("out")
ap.add_argument("--java-dir", default="src-test/src")
a = ap.parse_args()

units = [p for p in (re.sub(r"#.*", "", l).strip() for l in open(a.suite)) if p]
units_file = re.sub(r"\.txt$", ".units.json", a.suite)
leaves = json.load(open(units_file)) if os.path.exists(units_file) else {}
timings = json.load(open(a.timings)) if os.path.exists(a.timings) else {}
per_class = {}
for cls, secs in timings.items():          # fold inner classes (Outer$Inner) into their outer class
    per_class[cls.split("$")[0]] = per_class.get(cls.split("$")[0], 0) + secs
default = statistics.median(per_class.values()) if per_class else 1.0
cost = [sum(per_class.get(c, default) for c in leaves.get(u, [u])) for u in units]

def partition(cap):
    """Greedy contiguous split with max shard time <= cap; returns list of index lists or None."""
    shards, cur, acc = [], [], 0.0
    for i, c in enumerate(cost):
        if cur and acc + c > cap:
            shards.append(cur); cur, acc = [], 0.0
        cur.append(i); acc += c
    shards.append(cur)
    return shards if len(shards) <= a.n else None

lo, hi = max(cost), sum(cost)
for _ in range(60):                         # binary search on the bottleneck shard time
    mid = (lo + hi) / 2
    lo, hi = (lo, mid) if partition(mid) else (mid, hi)
shards = partition(hi)

ROOTS = ["src-test/src"] + glob.glob("modules_core/*/src-test") + glob.glob("modules/*/src-test")

def is_public(fq):
    for r in ROOTS:
        p = os.path.join(r, *fq.split(".")) + ".java"
        if os.path.exists(p):
            return re.search(rf"public\s+(final\s+|abstract\s+)?class\s+{fq.split('.')[-1]}\b", open(p).read()) is not None
    return True

def suite_java(i, idx, secs):
    """@SelectClasses keeps order but needs public classes (JUnit 1.9 has no `names=`); package-private
    ones are selected by package and narrowed with exact @IncludeClassNamePatterns covering the shard."""
    S = "org.junit.platform.suite.api."
    pub = [units[j] for j in idx if is_public(units[j])]
    priv = [units[j] for j in idx if not is_public(units[j])]
    ann = [f"@{S}Suite", f"@{S}SelectClasses({{\n    " + ",\n    ".join(f"{u}.class" for u in pub) + "\n})"]
    if priv:
        pkgs = sorted({u.rsplit(".", 1)[0] for u in priv})
        names = sorted({c for j in idx for c in leaves.get(units[j], [units[j]])} | set(pub) | set(priv))
        q = lambda s: '"' + s + '"'
        ann.append(f"@{S}SelectPackages({{" + ", ".join(q(p) for p in pkgs) + "})")
        ann.append(f"@{S}IncludeClassNamePatterns({{\n    " +
                   ",\n    ".join(q("^" + re.escape(n).replace("\\", "\\\\") + "(\\\\$.*)?$") for n in names) + "\n})")
    return (f"package {pkg};\n\n// GENERATED by .github/qa/plan-shards.py — shard {i}/{len(shards)}, ~{secs:.0f}s\n"
            + "\n".join(ann) + f"\npublic class QaShard{i} {{\n}}\n")

pkg = "org.openbravo.qa.shards"
jdir = os.path.join(a.java_dir, *pkg.split("."))
os.makedirs(a.out, exist_ok=True)
os.makedirs(jdir, exist_ok=True)
for i, idx in enumerate(shards, 1):
    secs = sum(cost[j] for j in idx)
    open(os.path.join(jdir, f"QaShard{i}.java"), "w").write(suite_java(i, idx, secs))
    open(os.path.join(a.out, f"shard-{i}.txt"), "w").write(
        f"# shard {i}/{len(shards)} — {len(idx)} units, estimated {secs:.0f}s\n{pkg}.QaShard{i}\n")
    print(f"shard {i}: {len(idx)} units, ~{secs:.0f}s", file=sys.stderr)
print(json.dumps({"shard": list(range(1, len(shards) + 1))}))
